"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9049],{45436:e=>{e.exports=JSON.parse('{"functions":[{"name":"init","desc":"Bootstrap hook. Registers the `Handlers` folder with `red` and drops leaving\\nplayers from `playersChoosing`, so an abandoned chooser does not leave a stale\\nauthorization behind. Also registers the `game_chooser` receipt callback,\\nthe only way a chooser opens.\\n\\nNo-ops entirely when the `Minigames` feature flag is off.","params":[],"returns":[],"function_type":"static","source":{"line":53,"path":"src/Server/Features/Minigames/MinigameService.luau"}},{"name":"getNextQueuedGame","desc":"Pops the next queued game, or returns `nil` if nothing is queued. Consuming \u2014\\n[GameService.gameWrap] calls this first each round and only falls back to\\nvoting when it comes back empty.","params":[],"returns":[{"desc":"","lua_type":"MinigameTypes.VotePoolItem?"}],"function_type":"static","source":{"line":88,"path":"src/Server/Features/Minigames/MinigameService.luau"}},{"name":"peekNextQueuedGame","desc":"The next queued game without removing it, or `nil` if nothing is queued.\\nWhat `MINIGAMES_NEXT_QUEUED_GAME` answers clients with.","params":[],"returns":[{"desc":"","lua_type":"MinigameTypes.VotePoolItem?"}],"function_type":"static","source":{"line":109,"path":"src/Server/Features/Minigames/MinigameService.luau"}},{"name":"getMinimumRequiredPlayers","desc":"The lowest `minimumPlayers` across every registered mode \u2014 the population at\\nwhich *something* becomes playable, not the requirement for any particular\\nmode.\\n\\nReturns `math.huge` if no modes are registered, which reads as \\"never enough\\nplayers\\" and keeps the lobby idle rather than starting a round with no mode to\\nrun.","params":[],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":128,"path":"src/Server/Features/Minigames/MinigameService.luau"}},{"name":"enoughPlayersInServer","desc":"Whether the server currently has enough players for at least one mode.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":150,"path":"src/Server/Features/Minigames/MinigameService.luau"}},{"name":"chooseNextGame","desc":"Records a player\'s pick and queues it for the next round.\\n\\nRejects anyone not in `playersChoosing` \u2014 that membership is the proof they\\nwere granted a pick, and it is consumed here so one grant yields exactly one\\npick. The player is then told their position in the queue.\\n\\nThe thumbnail is deliberately dropped (stored as `\\"\\"`); [GameService] looks the\\nreal map data up by name when the round starts.","params":[{"name":"player","desc":"The chooser","lua_type":"Player"},{"name":"payload","desc":"Their chosen mode and map","lua_type":"MinigameTypes.VotePoolItem"}],"returns":[],"function_type":"static","source":{"line":172,"path":"src/Server/Features/Minigames/MinigameService.luau"}},{"name":"canPlayerChoose","desc":"Remote responder: replies with whether the player may open a chooser \u2014 that\\nis, whether they do **not** already have one open. Used to gate the purchase\\nprompt on the client.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"`MINIGAMES_PLAYER_CAN_CHOOSE` carrying a boolean","lua_type":"red.Action"}],"function_type":"static","source":{"line":220,"path":"src/Server/Features/Minigames/MinigameService.luau"}},{"name":"startGameChooser","desc":"Opens the game chooser for a player: marks them as choosing and sends them one\\ncandidate per registered mode, each paired with a randomly drawn map from that\\nmode\'s list.\\n\\nReturns an error action if they already have a chooser open; otherwise returns\\n`nil` and the candidates arrive via a separate `MINIGAME_CHOOSE_GAME` dispatch.\\n\\nUnlike the vote pool, this is not filtered by player count \u2014 a chooser can pick\\na mode the current lobby is too small to run, and [GameService] drops it at\\nround start if the population still has not caught up.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"An error action, or nil on success","lua_type":"red.Action<nil>?"}],"function_type":"static","source":{"line":245,"path":"src/Server/Features/Minigames/MinigameService.luau"}}],"properties":[],"types":[],"name":"MinigameService","desc":"Handles the \\"choose the next game\\" path \u2014 the monetized alternative to voting.\\nA player who has been granted the right to choose picks a mode and map, and it\\nis appended to a FIFO queue that [GameService] drains ahead of running a vote.\\n\\nTwo pieces of module state: `gameQueue`, the pending picks, and\\n`playersChoosing`, the players with an open chooser. A player is added to\\n`playersChoosing` when their chooser opens and removed when they pick or leave,\\nso the entry doubles as the authorization token \u2014 [MinigameService.chooseNextGame]\\nrejects anyone not in it, which is what stops a client submitting an unpaid pick.\\n\\nGated by [FeatureFlags].Minigames \u2014 disabled by default; per-project forks\\nenable it deliberately. With the flag off `init` returns before registering the\\nremote handlers, so none of this is client-reachable.","tags":["dormant"],"realm":["Server"],"source":{"line":23,"path":"src/Server/Features/Minigames/MinigameService.luau"}}')}}]);